        return '<tr><td>' + s.name + '</td><td class="spk">' + (sp ? nhSparkSvg(sp, up) : '') + '</td><td class="px">' + s.last.toLocaleString('en-IN', { maximumFractionDigits: s.last > 999 ? 0 : 2 }) + '</td><td class="ch ' + (up ? 'up' : 'dn') + '">' + (up ? '\u25b2' : '\u25bc') + Math.abs(s.dM || 0).toFixed(1) + '%</td></tr>';
