    w.innerHTML=ico(T[8][2]).replace('<svg','<svg class="ico"')+'<span class="nm">Studio</span>'
      +'<svg class="cv" viewBox="0 0 24 24"><path d="m6 9.5 6 6 6-6"/></svg>'
