    panel.innerHTML = html;
    const all = nameMatches.concat((content || []).map(m => ({ type: 'content', tier: m.tier, index: m.index, q: q }))).concat(webItems.map(function (w) { return { type: 'web', url: w.url }; })).concat(webItems.length ? [{ type: 'ai', q: q }] : []);
