(function(){ if(document.getElementById("niy-ux-polish-css"))return; var s=document.createElement("style"); s.id="niy-ux-polish-css"; s.textContent="/* selection */::selection{background:var(--ds-accent-line,rgba(127,176,255,.28));color:var(--fg,#eef2f6)}/* unified interactive motion + pointer affordance */.tab,.toolbar-btn,.quick-controls button,.fin-card,.fin-tile,.fin-mv,.fin-vol-row,.feat-item,.rd-chip,.odds-row,.fin-xp-row,.fin-xp-tg,.fin-rg,.niy-bqt-act,.niy-bqt-row,.ai-web-toggle,.lang-toggle,.ck-item,.global-ai-close,.fin-link,.info-link,.niy-bqt-route.act{transition:background var(--ds-dur-1,150ms) var(--ds-ease,ease),border-color var(--ds-dur-1,150ms) var(--ds-ease,ease),color var(--ds-dur-1,150ms) var(--ds-ease,ease),box-shadow var(--ds-dur-1,150ms) var(--ds-ease,ease),transform var(--ds-dur-1,150ms) var(--ds-ease,ease)}.tab,.toolbar-btn,.feat-item,.fin-card,.fin-tile,.fin-mv,.fin-vol-row,.rd-chip,.odds-row,.fin-xp-row,.fin-xp-tg,.fin-rg,.niy-bqt-act,.ai-web-toggle,.fin-link{cursor:pointer}/* data-table row hover — dashboard signature */table.sample tbody tr[data-row-idx]{transition:background var(--ds-dur-1,150ms) var(--ds-ease,ease)}table.sample tbody tr[data-row-idx]:hover{background:var(--ds-accent-dim,rgba(127,176,255,.07)) !important}table.sample td{font-variant-numeric:tabular-nums}/* subtle press feedback (transform only — no layout shift) */.toolbar-btn:active,.tab:active,.fin-card:active,.fin-tile:active,.fin-vol-row:active,.fin-xp-tg:active,.fin-rg:active,.niy-bqt-act:active,.quick-controls button:active,.ai-web-toggle:active{transform:translateY(.5px)}/* interactive card hover — gentle border lift */.fin-card:hover,.fin-tile:hover,.odds-row:hover{border-color:var(--ds-accent-line,rgba(127,176,255,.35))}/* crisp focus rings for keyboard users */a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,[tabindex]:focus-visible,.feat-item:focus-visible,tr[data-row-idx]:focus-visible,.fin-xp-row:focus-visible,.tab:focus-visible{outline:2px solid var(--ds-accent,#7fb0ff);outline-offset:2px;border-radius:var(--ds-r-s,5px)}/* disabled-state clarity */button:disabled,.niy-bqt-act:disabled,.toolbar-btn:disabled{opacity:.5;cursor:not-allowed}/* reduced-motion respect */@media (prefers-reduced-motion:reduce){.tab,.toolbar-btn,.fin-card,.fin-tile,.fin-vol-row,.feat-item,.fin-xp-row,.fin-xp-tg,.fin-rg,.niy-bqt-act,.ai-web-toggle,table.sample tbody tr[data-row-idx]{transition:none !important}.toolbar-btn:active,.tab:active,.fin-card:active,.ai-web-toggle:active{transform:none !important}}"; document.head.appendChild(s); })();

