  var STATUS = {
    'active': { c: '#ff6f6f', l: 'ACTIVE' }, 'escalating': { c: '#ff8f3f', l: 'ESCALATING' },
    'ceasefire-fragile': { c: '#f0b429', l: 'CEASEFIRE · FRAGILE' }, 'under-review': { c: '#7fb0ff', l: 'UNDER REVIEW' }
  };
