    function avgDegree() { var HUB = { SOURCED_FROM: 1, MENTIONS: 1, ON_THEME: 1, GOVERNS: 1, IN_SECTOR: 1, EXPOSED_TO: 1 }; var h = G.edges.filter(function (e) { return HUB[e.type]; }).length; return 2 * h / Object.keys(G.nodes).length; }

