      if (!_hasContent) { ctx.fillStyle = cssVar('--fg-faint', '#9aa1a8'); ctx.font = '13px system-ui,sans-serif'; ctx.textAlign = 'center'; ctx.fillText('No connections in this view.', w / 2, h / 2); ctx.textAlign = 'left'; return; }
