        tagHtml = '<span class="nmg-strip-lab">Fields<\/span>' + tg.list.map(function (t) {
          return '<span class="nmg-strip-tag nmg-strip-tag-f" title="' + esc(t.k) + '">' + esc(clip(t.v, 30)) + '<\/span>';
        }).join('');
