  var PHASES=[{id:'approval',label:'AoN'},{id:'competition',label:'Competition'},{id:'contracted',label:'Contracted'},{id:'production',label:'Production'},{id:'development',label:'Development'},{id:'trials',label:'Trials'},{id:'delivery',label:'Delivery'},{id:'fielded',label:'Fielded'}];
  var SPEND=[{country:'United States',value:'$997.3B',gdp:'3.4% GDP'},{country:'China',value:'$313.7B',gdp:'1.7% GDP'},{country:'Russia',value:'$149.0B',gdp:'7.1% GDP'},{country:'Germany',value:'$88.5B',gdp:'1.9% GDP'},{country:'India',value:'$86.1B',gdp:'2.3% GDP'}];
  var selected=PROGRAMS[0],wasActive=false;
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function phaseLabel(id){var x=PHASES.filter(function(p){return p.id===id;})[0];return x?x.label:id;}
  function countBy(key,value){return PROGRAMS.filter(function(p){return p[key]===value;}).length;}
  function unique(key){var seen={};return PROGRAMS.map(function(p){return p[key];}).filter(function(v){if(seen[v])return false;seen[v]=1;return true;});}
  function optionHtml(key,all){return'<option value="">'+esc(all)+'</option>'+unique(key).sort().map(function(v){return'<option value="'+esc(v)+'">'+esc(v)+'</option>';}).join('');}
  function feedRowsHtml(list){if(!list.length)return'<tr><td class="giw-feedempty" colspan="7">No programme matches these filters</td></tr>';return list.map(function(p){return'<tr data-giw-id="'+esc(p.id)+'" tabindex="0" aria-label="Inspect '+esc(p.name)+'"><td title="'+esc(p.name)+'">'+esc(p.name)+'</td><td class="giw-svc" title="'+esc(p.service)+'">'+esc(p.service)+'</td><td title="'+esc(p.category)+'">'+esc(p.category)+'</td><td class="giw-phase" title="'+esc(p.stage)+'">'+esc(phaseLabel(p.phase))+'</td><td title="'+esc(p.qty)+'">'+esc(p.qty)+'</td><td class="giw-value" title="'+esc(p.value)+'">'+esc(p.value)+'</td><td class="giw-go">›</td></tr>';}).join('');}
  function spendHtml(){return'<section class="giw-spend" aria-label="Top military expenditure benchmarks"><div class="giw-spend-head"><b>Global defence-spend benchmarks · 2024 current US$</b><a href="https://www.sipri.org/sites/default/files/2025-04/2504_fs_milex_2024.pdf" target="_blank" rel="noreferrer">SIPRI source ↗</a></div><div class="giw-spend-grid">'+SPEND.map(function(x){return'<div class="giw-spend-card"><label>'+esc(x.country)+'</label><strong>'+esc(x.value)+'</strong><span>'+esc(x.gdp)+'</span></div>';}).join('')+'</div></section>';}
  function feedHtml(){var india=countBy('model','India-led'),approvals=countBy('phase','approval'),phaseOptions='<option value="">All phases</option>'+PHASES.map(function(x){return'<option value="'+esc(x.id)+'">'+esc(x.label)+'</option>';}).join('');return'<section class="giw-feed" aria-label="Global Intelligence programme monitor"><div class="giw-feedbar"><div class="giw-feedtitle"><b>Defence acquisition monitor</b><span>One source-linked register · updated through 22 Aug 2026</span></div><div class="giw-feedstats"><div class="giw-feedstat"><strong>'+PROGRAMS.length+'</strong><span>Tracked</span></div><div class="giw-feedstat"><strong>'+india+'</strong><span>India-led</span></div><div class="giw-feedstat"><strong>'+approvals+'</strong><span>At AoN</span></div></div></div><div class="giw-feedtools"><input class="giw-search" type="search" aria-label="Filter programmes" placeholder="Search programme, contractor or capability"><select class="giw-select giw-service-filter" aria-label="Filter by service">'+optionHtml('service','All services')+'</select><select class="giw-select giw-phase-filter" aria-label="Filter by phase">'+phaseOptions+'</select><select class="giw-select giw-model-filter" aria-label="Filter by industrial model">'+optionHtml('model','All origin models')+'</select></div><div class="giw-resultbar"><span><b data-giw-count>'+PROGRAMS.length+'</b> programmes shown</span><span>Click a row for verified event analytics</span></div><div class="giw-feedtablewrap"><table class="giw-feedtable"><colgroup><col style="width:31%"><col style="width:10%"><col style="width:17%"><col style="width:11%"><col style="width:13%"><col style="width:15%"><col style="width:3%"></colgroup><thead><tr><th>Programme</th><th>Service</th><th>Capability</th><th>Phase</th><th>Quantity</th><th style="text-align:right">Public value</th><th></th></tr></thead><tbody>'+feedRowsHtml(PROGRAMS)+'</tbody></table></div></section>'+spendHtml();}
  function filterFeed(host){var q=(host.querySelector('.giw-search').value||'').toLowerCase().trim(),svc=host.querySelector('.giw-service-filter').value,ph=host.querySelector('.giw-phase-filter').value,model=host.querySelector('.giw-model-filter').value;var list=PROGRAMS.filter(function(p){var hay=[p.name,p.service,p.category,p.stage,p.model,p.prime,p.partner,p.qty,p.value].join(' ').toLowerCase();return(!q||hay.indexOf(q)>-1)&&(!svc||p.service===svc)&&(!ph||p.phase===ph)&&(!model||p.model===model);}),tb=host.querySelector('tbody'),n=host.querySelector('[data-giw-count]');if(tb)tb.innerHTML=feedRowsHtml(list);if(n)n.textContent=String(list.length);paintRow();}
  function ensureFeed(){var body=document.querySelector('#detail .niy-col-feed .niy-col-body');if(!body||!isActive())return;var host=document.getElementById('giwProgrammeFeed');if(!host){host=document.createElement('div');host.id='giwProgrammeFeed';host.innerHTML=feedHtml();body.insertBefore(host,body.firstChild);host.querySelectorAll('.giw-search,.giw-select').forEach(function(c){c.addEventListener('input',function(){filterFeed(host);});c.addEventListener('change',function(){filterFeed(host);});});}}
  function isActive(){try{if(typeof activeTier!=='undefined'&&typeof activeIndex!=='undefined'&&typeof FEATURE_DATA!=='undefined'){var f=(FEATURE_DATA[activeTier]||[])[activeIndex];return !!(f&&f.dataSource&&f.dataSource.csv===MARKER);}}catch(e){}var x=document.querySelector('#sidebarList .feat-item.active .label');return !!(x&&x.textContent.replace(/\s*(AI|BETA)\s*$/,'').trim()==='Global Intelligence');}
  function railHtml(phase){return PHASES.map(function(x){return'<div class="giw-node '+(x.id===phase?'on':'')+'"><i></i>'+esc(x.label)+'</div>';}).join('');}
  function analyticalBrief(p){var phasePeers=countBy('phase',p.phase),servicePeers=countBy('service',p.service);return phaseLabel(p.phase)+' is the latest official position. '+phasePeers+' of '+PROGRAMS.length+' tracked records are at this phase; '+servicePeers+' relate to '+p.service+'. The decision point is '+p.next.charAt(0).toLowerCase()+p.next.slice(1);}
  function analyticsHtml(p){return'<div class="giw"><header class="giw-head"><i class="giw-head-mark"></i><div class="giw-head-copy"><h2>'+esc(p.name)+'</h2><p>'+esc(p.service)+' · '+esc(p.category)+' · '+esc(p.model)+'</p></div><span class="giw-stage">'+esc(p.stage)+'</span></header><section class="giw-section"><div class="giw-sec-head"><b>Programme at a glance</b><span>Official-record fields</span></div><div class="giw-kpis"><div class="giw-kpi"><label>Phase</label><strong>'+esc(phaseLabel(p.phase))+'</strong><span>'+esc(p.stage)+'</span></div><div class="giw-kpi"><label>Quantity</label><strong title="'+esc(p.qty)+'">'+esc(p.qty)+'</strong><span>Published scope</span></div><div class="giw-kpi"><label>Public value</label><strong title="'+esc(p.value)+'">'+esc(p.value)+'</strong><span>No allocation inferred</span></div><div class="giw-kpi"><label>Official update</label><strong>'+esc(p.updated)+'</strong><span>'+esc(p.sourceLabel)+'</span></div></div><div class="giw-official"><div class="giw-official-top"><label>Latest verified record</label><a class="giw-source" href="'+esc(p.source)+'" target="_blank" rel="noreferrer">Open source ↗</a></div><p>'+esc(p.detail)+'</p></div></section><section class="giw-section"><div class="giw-sec-head"><b>Acquisition route</b><span>Recorded position, not a score</span></div><div class="giw-rail">'+railHtml(p.phase)+'</div></section><section class="giw-section"><div class="giw-sec-head"><b>Industrial & delivery picture</b><span>Named entities</span></div><div class="giw-facts"><div class="giw-fact"><label>Prime / lead</label><strong title="'+esc(p.prime)+'">'+esc(p.prime)+'</strong></div><div class="giw-fact"><label>Indian partner / user</label><strong title="'+esc(p.partner)+'">'+esc(p.partner)+'</strong></div><div class="giw-fact"><label>Industrial model</label><strong>'+esc(p.model)+'</strong></div><div class="giw-fact"><label>Service</label><strong>'+esc(p.service)+'</strong></div></div><div class="giw-watch"><div><label>Monitor next</label><p>'+esc(p.next)+'</p></div><div><label>Evidence rule</label><p>Values appear only when disclosed by the cited record; package totals remain identified as package totals.</p></div></div></section><div class="giw-brief"><label>AI analyst brief</label><p>'+esc(analyticalBrief(p))+'</p></div><div class="giw-actions"><button type="button" class="giw-ai" data-giw-research>Research this programme</button><span class="giw-method">Selected record is attached automatically.</span></div></div>';}
  function cardFor(p){return{title:p.name,feature:'Global Intelligence',tier:'geopolitics',tierLabel:'Global',bucket:'Defence Acquisition',csv:MARKER,__giId:p.id,source:p.source,fields:{Programme:p.name,Service:p.service,Capability:p.category,Phase:p.stage,Quantity:p.qty,'Public value':p.value,'Industrial model':p.model,'Prime / lead':p.prime,'Indian partner / user':p.partner,'Official update':p.updated,'Verified record':p.detail,'Monitor next':p.next,'Primary source':p.source}};}
  function researchPrompt(p){return'Research '+p.name+' using the attached official programme record as the starting point. Verify the latest status after '+p.updated+', approval or contract milestones, quantities, disclosed value, delivery schedule, prime contractor, Indian partners, technology-transfer terms and confirmed delays. Separate confirmed facts from analysis. Cite every external claim and do not invent values, dates, completion percentages or risk scores.';}
  function ensureCard(p){if(!window.NiyAI||!Array.isArray(window.NiyAI.cards))return;for(var i=window.NiyAI.cards.length-1;i>=0;i--){if(window.NiyAI.cards[i]&&window.NiyAI.cards[i].csv===MARKER)window.NiyAI.cards.splice(i,1);}window.NiyAI.addCard(cardFor(p));}
  function openResearch(p){if(typeof window.openAiWorkspace==='function'){for(var i=(window.NiyAI&&window.NiyAI.cards?window.NiyAI.cards.length:0)-1;i>=0;i--){if(window.NiyAI.cards[i]&&window.NiyAI.cards[i].csv===MARKER)window.NiyAI.cards.splice(i,1);}window.openAiWorkspace(researchPrompt(p),cardFor(p));return;}if(typeof window.openGlobalAiWithPrompt==='function')window.openGlobalAiWithPrompt(researchPrompt(p));}
  function ensureResearchShell(){var pane=document.querySelector('#detail .niy-pane-ai');if(!pane||!isActive())return;var shell=pane.querySelector('.giw-research-shell');if(!shell){shell=document.createElement('div');shell.className='giw-research-shell';var log=pane.querySelector('.niy-ai-log');pane.insertBefore(shell,log||pane.firstChild);}shell.innerHTML='<label>Selected programme research</label><strong title="'+esc(selected.name)+'">'+esc(selected.name)+'</strong><div class="giw-research-prompts"><button type="button" data-giw-prompt="Verify the latest official status and cite the primary sources.">Verify latest</button><button type="button" data-giw-prompt="Map the prime contractor, Indian partners and critical supply chain.">Supply chain</button><button type="button" data-giw-prompt="Assess disclosed delivery milestones and identify confirmed delays only.">Delivery check</button></div>';}
  function resetScroll(includeFeed){var pane=document.querySelector('#detail .niy-pane-analytics');if(pane){pane.scrollTop=0;pane.scrollLeft=0;}var work=document.querySelector('#detail .niy-col-work .niy-work-body');if(work){work.scrollTop=0;work.scrollLeft=0;}if(includeFeed){var table=document.querySelector('#detail .giw-feedtablewrap'),feed=document.querySelector('#detail .niy-col-feed .niy-col-body');if(table){table.scrollTop=0;table.scrollLeft=0;}if(feed){feed.scrollTop=0;feed.scrollLeft=0;}}}
  function renderAnalytics(){var pane=document.querySelector('#detail .niy-pane-analytics');if(!pane||!isActive())return;pane.innerHTML=analyticsHtml(selected);pane.dataset.giwSelected=selected.id;resetScroll(false);var b=pane.querySelector('[data-giw-research]');if(b)b.onclick=function(){openResearch(selected);};}
  function programFromRow(tr){if(!tr)return null;var id=tr.getAttribute('data-giw-id');return PROGRAMS.filter(function(p){return p.id===id;})[0]||null;}
  function paintRow(){document.querySelectorAll('#detail .niy-col-feed tr[data-giw-id]').forEach(function(r){var p=programFromRow(r),on=!!(p&&p.id===selected.id),aria=on?'true':'false';if(r.classList.contains('giw-row-selected')!==on)r.classList.toggle('giw-row-selected',on);if(r.getAttribute('aria-selected')!==aria)r.setAttribute('aria-selected',aria);});}
  function labelModes(){var a=document.querySelector('#detail .niy-mode[data-mode="analytics"]'),i=document.querySelector('#detail .niy-mode[data-mode="ai"]');if(a&&a.textContent!=='Event Analytics')a.textContent='Event Analytics';if(i&&i.textContent!=='AI Research')i.textContent='AI Research';var input=document.querySelector('#detail .niy-pane-ai .niy-ai-input'),ph='Ask about the selected programme, supplier, schedule or strategic implication…';if(input&&input.placeholder!==ph)input.placeholder=ph;}
