    hamas:{type:'Counter-terrorism network',basis:'US, EU, UK and other terrorism authorities',instruments:['Asset freezes','Fundraiser and facilitator designations','Financial-sector notices','Crypto-address and exchange actions'],exemptions:['Humanitarian assistance not involving designated parties','Licensed relief and remittance channels'],watch:[['Fundraising networks','Observed','Charities, intermediaries and payment chains'],['Digital assets','Enforcement focus','Wallets, exchanges and conversion points'],['Regional facilitators','Monitor','Ownership, agency and control relationships']],market:[['Payments','Listed-party and intermediary exposure'],['Digital assets','Wallet and exchange screening'],['Non-profits','Governance and beneficiary diligence'],['Trade','Controlled-party and diversion risk']],trail:[['Long-running regime','Terrorism designations maintained across several jurisdictions'],['Recent packages','Financial and digital-asset facilitators added'],['Current record','Network analysis is more important than country-level screening']]},
