  function defaultMeta(p){return{type:'Targeted sanctions programme',basis:'Issuer-specific statutory and regulatory authorities',instruments:['Asset freezes','Transaction restrictions','Designation and ownership screening'],exemptions:['Humanitarian activity subject to applicable licences','Case-specific authorisations where issued'],watch:[['Ownership and control','Enforcement focus','Named parties, subsidiaries and beneficial owners'],['Payment route','Monitor','Banks, intermediaries and settlement path'],['Policy change','Monitor','New listings, delistings and licence updates']],market:[['Finance','Listed-party and transaction exposure'],['Trade','Counterparty and end-use diligence'],['Services','Issuer-specific prohibitions'],['Operations','Licence and recordkeeping requirements']],trail:[['Programme basis',p.reason],['Current record',p.impact],['Monitor next','Official designation, licence and enforcement updates']]};}
  function buildData(){var base=arr((window.NIY_GEO_SANCTIONS||{}).programs);return base.map(function(p){var m=META[p.id]||defaultMeta(p),sources=arr(p.sources).filter(function(s){return s&&s[0]&&s[1];});return Object.assign({},p,m,{sources:sources.length?sources:[['Official sanctions authority','https://ofac.treasury.gov/']],sectors:arr(p.sectors).length?p.sectors:['Targeted restrictions'],entities:p.entities||'Register-defined',impact:p.impact||'See official programme record.',status:p.status||'active'});});}
  var DATA=[],selected=null,forced=false,directHost=null,directMode='analytics',dragCard=null,aiObserver=null,wasActive=false,fitFrame=0;
  function isActive(){var a={};try{a=(window.niyActive?window.niyActive():null)||{};if(a.csv==='geo_sanctions')return true;if(forced&&a.csv&&a.csv!=='geo_sanctions'){forced=false;return false;}}catch(e){}var title=document.querySelector('#detail .detail-title,#detail .niy-title,#detail .niy-detail-title');if(forced){if(title&&title.textContent.replace(/\s*(AI|BETA)\s*$/,'').trim()!==FEATURE){forced=false;return false;}return true;}try{if(typeof activeTier!=='undefined'&&typeof activeIndex!=='undefined'&&typeof FEATURE_DATA!=='undefined'){var f=(FEATURE_DATA[activeTier]||[])[activeIndex];if(f&&f.feature)return f.feature===FEATURE;}}catch(e){}var x=document.querySelector('#sidebarList .feat-item.active .label');return !!((x&&x.textContent.replace(/\s*(AI|BETA)\s*$/,'').trim()===FEATURE)||(title&&title.textContent.replace(/\s*(AI|BETA)\s*$/,'').trim()===FEATURE));}
  function issuerTokens(p){var s=p.issuer||'',all=[['US','US'],['OFAC','US'],['EU','EU'],['UK','UK'],['UN','UN'],['Canada','Canada'],['Japan','Japan'],['Australia','Australia'],['AUS','Australia'],['S. Korea','South Korea']];var out=[];all.forEach(function(x){if(s.indexOf(x[0])>-1&&out.indexOf(x[1])<0)out.push(x[1]);});return out.length?out:['Other'];}
  function countIssuers(){var o={};DATA.forEach(function(p){issuerTokens(p).forEach(function(x){o[x]=1;});});return Object.keys(o).length;}
  function countSectors(){var o={};DATA.forEach(function(p){p.sectors.forEach(function(x){o[x.split(/[(&]/)[0].trim()]=1;});});return Object.keys(o).length;}
  function regions(){return Array.from(new Set(DATA.map(function(p){return p.region;}))).sort();}
  function types(){return Array.from(new Set(DATA.map(function(p){return p.type;}))).sort();}
  function mapPoint(lat,lon){return{x:(lon+180)/360*100,y:(90-lat)/180*100};}
  var ISSUER_POS={'US':[38.9,-77],'EU':[50.85,4.35],'UK':[51.5,-.1],'UN':[40.75,-73.97],'Canada':[45.42,-75.7],'Japan':[35.68,139.69],'Australia':[-35.28,149.13],'South Korea':[37.56,126.97],'Other':[47,8]};
  function qpath(a,b){var x1=a.x*10,y1=a.y*5,x2=b.x*10,y2=b.y*5,mx=(x1+x2)/2,my=Math.min(y1,y2)-Math.min(90,Math.abs(x2-x1)*.12+20);return'M '+x1+' '+y1+' Q '+mx+' '+my+' '+x2+' '+y2;}
  function mapSvg(){var target=mapPoint(selected.lat,selected.lon),arcs=issuerTokens(selected).map(function(k){var v=ISSUER_POS[k]||ISSUER_POS.Other,p=mapPoint(v[0],v[1]);return'<path class="snw-arc is-selected" d="'+qpath(p,target)+'"/>';}).join('');var pts=DATA.map(function(p){var q=mapPoint(p.lat,p.lon),on=p.id===selected.id;return'<g class="snw-point '+(on?'is-selected':'')+'" data-snw-id="'+esc(p.id)+'" data-status="'+esc(p.status)+'" transform="translate('+(q.x*10).toFixed(1)+' '+(q.y*5).toFixed(1)+')"><circle r="7"></circle><circle r="3.2"></circle><text x="9" y="3">'+esc(p.name)+'</text></g>';}).join('');return'<svg viewBox="0 0 1000 500" preserveAspectRatio="none" role="img" aria-label="Map of tracked sanctions targets and issuer links">'+arcs+pts+'</svg>';}
  function mapCardHtml(){return'<label>Selected programme</label><h4>'+esc(selected.name)+'</h4><div class="snw-mapmeta">'+esc(selected.region)+' · '+esc(selected.type)+'</div><div class="snw-issuerline"><b>Target</b><br>'+esc(selected.target)+'<br><br><b>Issuers</b><br>'+esc(selected.issuer)+'</div><button type="button" data-snw-research>Request AI analysis</button>';}
  function feedRows(list){if(!list.length)return'<tr><td class="snw-empty" colspan="6">No sanctions programme matches these filters</td></tr>';return list.map(function(p){return'<tr tabindex="0" draggable="true" data-snw-drag="1" data-snw-id="'+esc(p.id)+'" aria-label="Drag '+esc(p.name)+' to AI Research" class="'+(selected&&p.id===selected.id?'snw-selected':'')+'"><td title="'+esc(p.name)+'">'+esc(p.name)+'</td><td title="'+esc(p.issuer)+'">'+esc(p.issuer)+'</td><td title="'+esc(p.sectors.join(', '))+'">'+esc(p.sectors.slice(0,2).join(' · '))+'</td><td class="snw-count">'+esc(p.entities)+'</td><td><span class="snw-status" data-status="'+esc(p.status)+'">'+esc(p.status)+'</span></td><td class="snw-go">›</td></tr>';}).join('');}
  function options(list,label){return'<option value="">'+label+'</option>'+list.map(function(x){return'<option value="'+esc(x)+'">'+esc(x)+'</option>';}).join('');}
  function feedHtml(){return'<section class="snw-feed"><div class="snw-command"><div><h3>Sanctions monitor</h3><p>Programme register · official-source links · selected issuer-to-target route</p></div><div class="snw-stats"><div class="snw-stat"><strong>'+DATA.length+'</strong><span>regimes</span></div><div class="snw-stat"><strong>'+countIssuers()+'</strong><span>issuer groups</span></div><div class="snw-stat"><strong>'+regions().length+'</strong><span>regions</span></div></div></div><div class="snw-tools"><input class="snw-search" type="search" placeholder="Search programme, issuer or sector" aria-label="Search sanctions regimes"><select class="snw-select snw-region">'+options(regions(),'All regions')+'</select><select class="snw-select snw-type-filter">'+options(types(),'All regime types')+'</select><select class="snw-select snw-status-filter">'+options(['active','escalating','under-review'],'All statuses')+'</select></div><div class="snw-mapframe"><div class="snw-map"><span class="snw-maplabel">Selected issuer-to-target route</span>'+mapSvg()+'<div class="snw-mapkey"><span><i class="snw-dot red"></i>Selected</span><span><i class="snw-dot"></i>Tracked target</span></div></div><aside class="snw-mapcard">'+mapCardHtml()+'</aside></div><div class="snw-result"><span><b data-snw-count>'+DATA.length+'</b> programmes</span><span>Select a programme for analysis</span></div><div class="snw-tablewrap"><table class="snw-table"><colgroup><col style="width:25%"><col style="width:24%"><col style="width:25%"><col style="width:13%"><col style="width:10%"><col style="width:3%"></colgroup><thead><tr><th>Programme / target</th><th>Issuing authorities</th><th>Economic perimeter</th><th style="text-align:right">Listed scope</th><th>Status</th><th></th></tr></thead><tbody>'+feedRows(DATA)+'</tbody></table></div></section>';}
  function rankedCounts(values){var counts={};values.forEach(function(v){if(v)counts[v]=(counts[v]||0)+1;});return Object.keys(counts).map(function(k){return{name:k,count:counts[k]};}).sort(function(a,b){return b.count-a.count||a.name.localeCompare(b.name);});}
  function sectorFamilyCount(){var seen={};DATA.forEach(function(p){p.sectors.forEach(function(s){seen[s]=1;});});return Object.keys(seen).length;}
  function portfolioBars(items,limit){var list=items.slice(0,limit||5),max=list.reduce(function(m,x){return Math.max(m,x.count);},1);return'<div class="snw-port-bars">'+list.map(function(x){return'<div class="snw-port-row"><label title="'+esc(x.name)+'">'+esc(x.name)+'</label><span class="snw-port-track"><i class="snw-port-fill" style="width:'+Math.max(6,Math.round(x.count/max*100))+'%"></i></span><strong>'+x.count+'</strong></div>';}).join('')+'</div>';}
  function analyticsWorkspaceHtml(p){var regionCounts=rankedCounts(DATA.map(function(x){return x.region;})),issuerCounts=rankedCounts([].concat.apply([],DATA.map(issuerTokens)));return'<div class="snw-selection-strip"><i></i><div><h2>'+esc(p.name)+'</h2><p>'+esc(p.region)+' · '+esc(p.type)+' · '+esc(p.target)+'</p></div><span class="sna-status">'+esc(p.status)+'</span></div><div class="snw-portfolio-kpis"><div class="snw-portfolio-kpi"><label>Regimes tracked</label><strong>'+DATA.length+'</strong><span>Source-linked programme records</span></div><div class="snw-portfolio-kpi"><label>Issuer groups</label><strong>'+countIssuers()+'</strong><span>Recorded issuing jurisdictions</span></div><div class="snw-portfolio-kpi"><label>Target regions</label><strong>'+regions().length+'</strong><span>Normalized programme geography</span></div><div class="snw-portfolio-kpi"><label>Sector families</label><strong>'+sectorFamilyCount()+'</strong><span>Named restricted sectors</span></div></div><div class="snw-visual-grid"><div class="snw-map"><span class="snw-maplabel">Issuer-to-target routes · selected: '+esc(p.name)+'</span>'+mapSvg()+'<div class="snw-mapkey"><span><i class="snw-dot red"></i>Selected programme</span><span><i class="snw-dot"></i>Tracked target</span></div></div><aside class="snw-chart-stack"><div class="snw-port-chart"><div class="snw-port-chart-head"><b>Programmes by target region</b><span>Record count</span></div>'+portfolioBars(regionCounts,5)+'</div><div class="snw-port-chart"><div class="snw-port-chart-head"><b>Issuer group presence</b><span>Programme count</span></div>'+portfolioBars(issuerCounts,5)+'</div></aside></div>'+analyticsHtml(p);}
  function primarySource(p){return p.sources[0]||['Official source','https://ofac.treasury.gov/'];}
  function analyticalBrief(p){return p.name+' combines '+p.instruments.slice(0,2).join(' and ').toLowerCase()+' across '+p.sectors.slice(0,3).join(', ')+'. The immediate analytical focus is '+p.watch[0][0].toLowerCase()+'; compliance decisions should be checked against the issuing authority, ownership rules and current licence text.';}
  function analyticsHtml(p){var src=primarySource(p),watch=p.watch.map(function(x){var tone=/observed/i.test(x[1])?'observed':/focus/i.test(x[1])?'focus':'';return'<div class="sna-now-row"><div><b>'+esc(x[0])+'</b><p>'+esc(x[2])+'</p></div><span class="sna-tag" data-tone="'+tone+'">'+esc(x[1])+'</span></div>';}).join('');return'<div class="sna"><header class="sna-head"><i class="sna-mark"></i><div class="sna-headcopy"><h2>'+esc(p.name)+'</h2><p>'+esc(p.region)+' · '+esc(p.type)+'</p></div><span class="sna-status">'+esc(p.status)+'</span></header><nav class="sna-tabs" aria-label="Sanctions analytics views"><button type="button" class="active" data-sna-tab="overview">Overview</button><button type="button" data-sna-tab="restrictions">Restrictions</button><button type="button" data-sna-tab="exposure">Exposure</button></nav><div class="sna-view" data-sna-view="overview"><section class="sna-section"><div class="sna-kpis"><div class="sna-kpi"><label>Target</label><strong title="'+esc(p.target)+'">'+esc(p.target)+'</strong><span>Recorded perimeter</span></div><div class="sna-kpi"><label>Listed scope</label><strong>'+esc(p.entities)+'</strong><span>Register descriptor</span></div><div class="sna-kpi"><label>Issuers</label><strong>'+issuerTokens(p).length+'</strong><span title="'+esc(p.issuer)+'">'+esc(p.issuer)+'</span></div><div class="sna-kpi"><label>Sector coverage</label><strong>'+p.sectors.length+'</strong><span>'+esc(p.sectors.slice(0,2).join(' · '))+'</span></div></div><div class="sna-lead"><div class="sna-leadtop"><label>Policy objective</label><a class="sna-source" href="'+esc(src[1])+'" target="_blank" rel="noreferrer">'+esc(src[0])+' ↗</a></div><p>'+esc(p.reason)+'</p></div></section><div class="sna-summary"><label>AI analyst brief</label><p>'+esc(analyticalBrief(p))+'</p></div><section class="sna-section" style="margin-top:15px"><div class="sna-sechead"><b>Monitor now</b><span>Evidence categories</span></div><div class="sna-now">'+watch+'</div></section><div class="sna-actions"><button type="button" class="sna-ai" data-snw-research>Research this regime</button><span class="sna-method">Verify official lists and licence text before action.</span></div></div><div class="sna-view" data-sna-view="restrictions" hidden><section class="sna-section"><div class="sna-sechead"><b>Legal & economic perimeter</b><span>What is actually restricted</span></div><div class="sna-facts"><div class="sna-fact"><label>Regime form</label><strong>'+esc(p.type)+'</strong></div><div class="sna-fact"><label>Legal basis</label><strong>'+esc(p.basis)+'</strong></div><div class="sna-fact"><label>Issuing authorities</label><strong>'+esc(p.issuer)+'</strong></div><div class="sna-fact"><label>Primary target</label><strong>'+esc(p.target)+'</strong></div></div><div class="sna-chips">'+p.sectors.map(function(x){return'<span class="sna-chip">'+esc(x)+'</span>';}).join('')+'</div><div class="sna-instruments">'+p.instruments.map(function(x,i){return'<div class="sna-instrument"><label>'+(i===0?'Primary measure':'Additional measure')+'</label><span>'+esc(x)+'</span></div>';}).join('')+'<div class="sna-instrument"><label>Licences / exceptions</label><span>'+esc(p.exemptions.join('; '))+'</span></div></div></section><div class="sna-actions"><button type="button" class="sna-ai" data-snw-research>Verify current rules</button><span class="sna-method">Issuer rules may differ.</span></div></div><div class="sna-view" data-sna-view="exposure" hidden><section class="sna-section"><div class="sna-sechead"><b>Enforcement & evasion watch</b><span>Categorical evidence · no scores</span></div><div class="sna-now">'+watch+'</div></section><section class="sna-section"><div class="sna-sechead"><b>Market transmission</b><span>Exposure channels, not impact estimates</span></div><div class="sna-market">'+p.market.map(function(x){return'<div><label>'+esc(x[0])+'</label><p>'+esc(x[1])+'</p></div>';}).join('')+'</div></section><section class="sna-section"><div class="sna-sechead"><b>Decision trail</b><span>Programme chronology</span></div><div class="sna-trail">'+p.trail.map(function(x){return'<div class="sna-event"><label>'+esc(x[0])+'</label><p>'+esc(x[1])+'</p></div>';}).join('')+'</div></section></div></div>';}
  var SAN_EU=['Austria','Belgium','Bulgaria','Croatia','Cyprus','Czechia','Denmark','Estonia','Finland','France','Germany','Greece','Hungary','Ireland','Italy','Latvia','Lithuania','Luxembourg','Malta','Netherlands','Poland','Portugal','Romania','Slovakia','Slovenia','Spain','Sweden'];
  function sanctionTargetCountries(p){var s=((p.id||'')+' '+(p.name||'')+' '+(p.target||'')).toLowerCase(),out=[];function add(x){if(out.indexOf(x)<0)out.push(x);}if(/russia|russian/.test(s))add('Russian Federation');if(/\biran\b/.test(s))add('Iran');if(/north korea|dprk/.test(s))add('North Korea');if(/myanmar|burma/.test(s))add('Myanmar');if(/venezuela/.test(s))add('Venezuela');if(/belarus/.test(s))add('Belarus');if(/cuba/.test(s))add('Cuba');if(/zimbabwe/.test(s))add('Zimbabwe');if(/nicaragua/.test(s))add('Nicaragua');if(/syria/.test(s))add('Syria');if(/china|xinjiang|uflpa/.test(s))add('China');if(/mali|\baes\b/.test(s))add('Mali');if(/houthi|ansar allah|yemen/.test(s))add('Yemen');if(/hamas|pij/.test(s))add('Palestine');if(/hezbollah/.test(s))add('Lebanon');if(/fentanyl|drug cartel/.test(s))add('Mexico');return out;}
